import pyomo.environ as pyo

DATA = {
    "roles": ["Doctor", "Nurse"],
    "patients_per_staff": {"Doctor": 2, "Nurse": 3},
    "min_patients": 10,
    "max_staff": 12,
    "cost_per_staff": {"Doctor": 5, "Nurse": 3},
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.ROLES = pyo.Set(initialize=d["roles"])

    model.staff = pyo.Var(
        model.ROLES,
        within=pyo.NonNegativeIntegers,
        bounds=(0, d["max_staff"]),
    )

    def obj_rule(m):
        return sum(d["cost_per_staff"][r] * m.staff[r] for r in m.ROLES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def patient_coverage_rule(m):
        return sum(
            d["patients_per_staff"][r] * m.staff[r] for r in m.ROLES
        ) >= d["min_patients"]

    model.patient_coverage = pyo.Constraint(rule=patient_coverage_rule)

    def headcount_rule(m):
        return sum(m.staff[r] for r in m.ROLES) <= d["max_staff"]

    model.headcount_limit = pyo.Constraint(rule=headcount_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "staff": ["doctor", "nurse"],
    "patients_per_staff": {"doctor": 2, "nurse": 3},
    "cost_per_staff": {"doctor": 5, "nurse": 3},
    "min_patients": 10,
    "max_total_staff": 12,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.STAFF = pyo.Set(initialize=d["staff"])

    model.x = pyo.Var(
        model.STAFF,
        domain=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["cost_per_staff"][s] * m.x[s] for s in m.STAFF)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def patient_coverage_rule(m):
        return sum(
            d["patients_per_staff"][s] * m.x[s] for s in m.STAFF
        ) >= d["min_patients"]

    model.patient_coverage = pyo.Constraint(rule=patient_coverage_rule)

    def total_staff_rule(m):
        return sum(m.x[s] for s in m.STAFF) <= d["max_total_staff"]

    model.total_staff_limit = pyo.Constraint(rule=total_staff_rule)

    return model
